query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        businessPartner {
          id
          name
        }
        businessPartnerAddress {
          id
          textAddress
          address {
            lines
            city
            state
          }
        }
        orderLines {
          edges {
            node {
              productId
              orderLineReleases {
                total
                edges {
                  node {
                    id
                    quantity {
                      value
                      unitId
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

query PickStep($where: PickStepWhereInput, $orderBy: [PickStepOrderByInput!], $first: Int, $after: String) {
  pickStep(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        
      }
    }
  }
}

